/**
 * Regenerate src/hawiyat/fallback-models.ts from the live gateway.
 * Usage: HAWIYAT_API_KEY=... bun run models:refresh
 */
import { writeFileSync } from "node:fs"
import { fetchModels, isCustomerFacingModelId } from "../src/hawiyat/catalog"

const key = process.env.HAWIYAT_API_KEY
if (!key) throw new Error("Set HAWIYAT_API_KEY")

const models = (await fetchModels(key, AbortSignal.timeout(20_000))).filter((m) =>
  isCustomerFacingModelId(m.id),
)

const header =
  "/**\n * Bundled fallback model catalog.\n *\n" +
  " * GENERATED by scripts/capture-fallback.ts — do not edit by hand.\n" +
  ` * Source: GET https://ai.hawiyat.cloud/v1/models at ${new Date().toISOString()}\n` +
  " *\n" +
  " * Cold-start fallback shown before the first successful `/v1/models` refresh\n" +
  " * (which replaces it). Filtered to customer-facing ids: gateway-internal\n" +
  " * routing/leaf names must never surface to customers.\n" +
  " */\nimport type { CatalogModel } from \"./catalog\"\n\n"

writeFileSync(
  new URL("../src/hawiyat/fallback-models.ts", import.meta.url),
  header + "export const FALLBACK_MODELS: CatalogModel[] = " + JSON.stringify(models, null, 2) + "\n",
)
